cat >> style.css <<'EOF'

/* ---------- CAMPAIGN / MISSION SELECT ---------- */
.mission-screen{position:fixed;inset:0;z-index:60;overflow:auto;padding:26px 42px 22px;background:#e9e9df;background-image:radial-gradient(#cfd4c8 .7px,transparent .7px);background-size:12px 12px;-webkit-overflow-scrolling:touch}
.mission-screen[hidden]{display:none}
.mission-inner{max-width:1180px;margin:0 auto;min-height:calc(100vh - 48px);display:flex;flex-direction:column;gap:20px}
.mission-top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d5d9ce;padding-bottom:15px}
.mission-close{display:flex;align-items:center;gap:8px;border:1px solid #d5dacf;background:#f7f6ef;border-radius:8px;padding:9px 13px;font:800 9px 'DM Sans',sans-serif;letter-spacing:1px;color:#5c6b5c;cursor:pointer;transition:.16s}
.mission-close:hover{background:#edf2e7;border-color:#c5d6b3}
.mission-hero{display:flex;justify-content:space-between;align-items:flex-end;gap:26px;padding-top:4px}
.mission-hero h2{font:900 50px/.92 'Barlow Condensed',sans-serif;letter-spacing:1px;margin:10px 0 8px}
.mission-hero h2 em{font-style:normal;color:#4e9a4f}
.mission-sub{margin:0;max-width:530px;font-size:12px;line-height:1.6;color:#728075}
.mission-stats{display:flex;gap:9px;flex:none}
.mission-stats div{background:#27382b;color:#fff;border-radius:10px;padding:12px 15px;min-width:104px;display:flex;flex-direction:column;gap:5px;position:relative;overflow:hidden}
.mission-stats div:after{content:'';position:absolute;right:-18px;bottom:-24px;width:64px;height:64px;border:1px solid #ffffff0d;border-radius:50%;box-shadow:0 0 0 10px #ffffff08}
.mission-stats small{font-size:7px;font-weight:800;letter-spacing:1px;color:#aebfa6}
.mission-stats strong{font:800 22px 'Barlow Condensed',sans-serif;letter-spacing:.6px;color:#dceb92}
.mission-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}
