const fs = require('fs');

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function main() {
  const { execSync } = require('child_process');
  let list;
  for (let i = 0; i < 20; i++) {
    try {
      list = await (await fetch('http://127.0.0.1:9222/json/list')).json();
      break;
    } catch (e) { await sleep(300); }
  }
  const page = list.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0;
  const pending = new Map();
  ws.onmessage = e => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
  };
  await new Promise(r => (ws.onopen = r));
  const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });

  await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: 'http://localhost:3002' });
  await sleep(2200);

  const mode = process.argv[2] || 'level2';

  if (mode === 'level2') {
    await send('Runtime.evaluate', { expression: `document.querySelector('.mission-card[data-level="1"]').click()` });
    await sleep(2200);
    const shot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80 });
    fs.writeFileSync('/tmp/opencode/pvz-l2.jpg', Buffer.from(shot.result.data, 'base64'));
  }

  if (mode === 'win') {
    await send('Runtime.evaluate', { expression: `document.querySelector('.mission-card[data-level="0"]').click()` });
    await sleep(600);
    await send('Runtime.evaluate', {
      expression: `
        const o=document.getElementById('fieldOverlay');
        o.hidden=false;
        document.getElementById('overlayKicker').textContent='FIELD REPORT · LEVEL 01';
        document.getElementById('overlayTitle').textContent='SECTOR SECURED';
        const s=document.getElementById('overlayStars'); s.hidden=false; s.innerHTML='<i class="on">★</i><i class="on">★</i><i class="on">★</i>';
        document.getElementById('overlayText').textContent='24 hostiles neutralized · 3 of 3 lane mowers intact · best ★★★';
        const r=document.getElementById('overlayReward'); r.hidden=false;
        r.innerHTML='<small>NEXT ASSIGNMENT · LEVEL 02</small><b>DIG IN — THE EAST RIDGE</b><small>NEW UNIT ISSUED · 🥔 BUNKER BULB</small>';
        document.getElementById('overlayPrimary').innerHTML='NEXT MISSION <span>→</span>';
        true;
      `
    });
    await sleep(500);
    const shot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80 });
    fs.writeFileSync('/tmp/opencode/pvz-win.jpg', Buffer.from(shot.result.data, 'base64'));
  }

  if (mode === 'mobile') {
    await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
    await send('Page.navigate', { url: 'http://localhost:3002' });
    await sleep(2000);
    const shot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80 });
    fs.writeFileSync('/tmp/opencode/pvz-mobile.jpg', Buffer.from(shot.result.data, 'base64'));
  }

  ws.close();
  console.log('done', mode);
}
main().catch(e => { console.error(e); process.exit(1); });

