const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function main() {
  const list = await (await fetch('http://127.0.0.1:9222/json/list')).json();
  const page = list.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0;
  const pending = new Map();
  ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
  await new Promise(r => (ws.onopen = r));
  const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  await send('Page.enable');
  await send('Runtime.evaluate', { expression: `document.getElementById('overlaySecondary').click()` });
  await sleep(700);
  const info = await send('Runtime.evaluate', { expression: `JSON.stringify({
    l2disabled: document.querySelector('.mission-card[data-level="1"]').disabled,
    l2status: document.querySelector('.mission-card[data-level="1"] .mc-status').textContent,
    l1stars: document.querySelector('.mission-card[data-level="0"] .mc-stars').textContent,
    sectors: document.getElementById('msSectors').textContent,
    stars: document.getElementById('msStars').textContent
  })` });
  console.log(info.result.result.value);
  const s = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80 });
  fs.writeFileSync('/tmp/opencode/shot.jpg', Buffer.from(s.result.data, 'base64'));
  ws.close();
}
main().catch(e => { console.error(e); process.exit(1); });

