const sleep = ms => new Promise(r => setTimeout(r, ms));
async function main() {
  const list = await (await fetch('http://127.0.0.1:9222/json/list')).json();
  const page = list.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0;
  const pending = new Map();
  ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
  await new Promise(r => (ws.onopen = r));
  const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: 'http://localhost:3002' });
  await sleep(1800);
  const ev = async expr => (await send('Runtime.evaluate', { expression: expr })).result.result.value;
  console.log('menu visible on load:', await ev(`!document.getElementById('missionScreen').hidden`));
  console.log('cards:', await ev(`document.querySelectorAll('.mission-card').length`));
  await ev(`document.querySelector('.mission-card[data-level="0"]').click()`);
  await sleep(300);
  console.log('menu closed after pick:', await ev(`document.getElementById('missionScreen').hidden`));
  await ev(`document.getElementById('missionsBtn').click()`);
  await sleep(200);
  console.log('menu reopens:', await ev(`!document.getElementById('missionScreen').hidden`));
  await ev(`document.getElementById('missionsClose').click()`);
  await sleep(200);
  console.log('close btn works:', await ev(`document.getElementById('missionScreen').hidden`));
  await ev(`document.getElementById('pauseBtn').click()`);
  await sleep(300);
  console.log('pause label:', await ev(`document.getElementById('pauseBtn').textContent`));
  console.log('seed bank chips:', await ev(`document.querySelectorAll('.sb-unit').length`));
  const s = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80 });
  require('fs').writeFileSync('/tmp/opencode/shot.jpg', Buffer.from(s.result.data, 'base64'));
  ws.close();
}
main().catch(e => { console.error(e); process.exit(1); });

const sleep = ms => new Promise(r => setTimeout(r, ms));
async function main() {
  const list = await (await fetch('http://127.0.0.1:9222/json/list')).json();
  const page = list.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0;
  const pending = new Map();
  ws.onmessage = e => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); return; }
    if (m.method === 'Runtime.exceptionThrown') console.log('EXC', JSON.stringify(m.params.exceptionDetails).slice(0, 1200));
    if (m.method === 'Log.entryAdded') console.log('LOG', m.params.entry.level, m.params.entry.text);
  };
  await new Promise(r => (ws.onopen = r));
  const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  await send('Runtime.enable');
  await send('Log.enable');
  await send('Page.enable');
  await send('Page.navigate', { url: 'http://localhost:3002/?t=' + Date.now() });
  await sleep(2500);
  const ev = async expr => (await send('Runtime.evaluate', { expression: expr })).result.result.value;
  console.log('readyState', await ev('document.readyState'));
  console.log('scripts', await ev(`[...document.scripts].map(s=>s.src).join(',')`));
  console.log('menu hidden', await ev(`document.getElementById('missionScreen').hidden`));
  console.log('cards', await ev(`document.querySelectorAll('.mission-card').length`));
  console.log('grid html len', await ev(`document.getElementById('missionGrid').innerHTML.length`));
  console.log('unit cards', await ev(`document.querySelectorAll('.unit-card').length`));
  ws.close();
}
main().catch(e => { console.error(e); process.exit(1); });

